# Generated by manage.py generate_test_cases.
from django.core.files.uploadedfile import SimpleUploadedFile

from bloomerp.form_fields.files_relation_field import FilesRelationField
from bloomerp.tests.base import BloomerpFormFieldTestCase, FormFieldScenario


class TestFilesRelationFieldFormField(BloomerpFormFieldTestCase):
    field_class = FilesRelationField

    def get_test_scenarios(self) -> list[FormFieldScenario[FilesRelationField]]:
        """Validate new uploads separately from existing attachment display values."""
        upload = SimpleUploadedFile("report.txt", b"report")
        return [
            FormFieldScenario(
                name="Uploads remain deferred until the parent saves",
                clean_value=[upload],
                clean_result_validators=lambda value: (
                    value.files == [upload]
                    and value.saved_file_ids == []
                    and value.serialize() == ["report.txt"]
                ),
            ),
            FormFieldScenario(
                name="Existing display identifiers are not treated as uploads",
                constructor_kwargs={"required": False},
                clean_value=["previous-file-id"],
                clean_result_validators=lambda value: value.files == [],
            ),
        ]
